      triggerTests.push([lines, cursorLine, cursorCol]);
      return false;
    },
  } satisfies AutocompleteProvider;
  const wrapper = wrap(current);
  const expectedTriggerTests = [[[OWN_COMMAND_LINE], 0, 23]];

