		registry: tracingRegistry(trace),
		stateLockPort: lock.port,
		statePort: tracingStatePort(trace),
	});

	assert(result.success);

	expect(lock.acquired).toStrictEqual(["production"]);
	expect(lock.released).toStrictEqual(["production"]);
});

