  return { fake, bundle, blob };
}

async function open(fake: FakeGateway, extra: Record<string, unknown> = {}) {
  return DecdnClient.open({
    gatewayUrl: fake.url,
    fetch: fake.fetch,
    ...extra,
  });
}

