    await qm.pushBatch(QUEUE, [
      { data: { i: 0 } },
      { data: { i: 1 } },
      { data: { i: 2 } },
    ]);

    const pulled = await pullPromise;
    expect(pulled).not.toBeNull();
  });
});

describe('Progress Message Edge Cases', () => {
