test('count should return correct queue count', async () => {
  const QUEUE = 'count-queue';

  // Empty queue
  expect(qm.count(QUEUE)).toBe(0);

  // Push jobs
  for (let i = 0; i < 5; i++) {
    await qm.push(QUEUE, { data: { i } });
  }

