  const app = await makeApp();
  const m = inboxStore.add({ priority: 'medium', source: 'manual', title: 't', body: 'b' });
  // Publish 3 events; client claims to have seen up to id 1.
  inboxEventBus.publish(m.id, { type: 'a', data: {} });
