  const selection = selectNextPracticeItem(modeDeck([
    { id: 'alpha', modes: ['flashcards'] },
    { id: 'beta', modes: ['choice'] },
  ]), {
    now: NOW,
    history,
  });

  expect(selection?.lemma.lemmaId).toBe('alpha');
