function reviewEntry(index: number, card = 'alpha'): ReviewLogEntry {
  const reviewedAt = NOW.getTime() + index * 60_000;
  return {
    cardKey: cardKey(card, 'flashcards'),
    lemmaId: card,
    mode: 'flashcards',
