      { lemmaId: 'missing', origin: 'new' as const },
      { lemmaId: 'missing', origin: 'new' as const },
    ],
  };
  const refilled = refillDailyPracticeDeckSnapshot(tampered, index, cards, {
    date: '2026-06-23',
