import { expect, type Locator, type Page } from '@playwright/test'
import { test } from './workspace-fixture'

async function expectPhoneProjectTabs(page: Page) {
  await page.evaluate(() => document.fonts.ready)
  // Pin reference padding and gaps without depending on native hairline rounding.
  const tabs = page.locator('.project-detail-page__tab')
  await expect(tabs).toHaveCount(3)
  const boxes = await tabs.evaluateAll(elements => elements.map(element => {
    const box = element.getBoundingClientRect(), style = getComputedStyle(element)
    const text = element.querySelector(':scope > div')!.getBoundingClientRect()
    return { x: box.x, right: box.right, inset: text.x - box.x - element.clientLeft, padding: style.paddingLeft }
  }))
  expect(boxes[0].x).toBe(8)
  for (const [index, box] of boxes.entries()) {
    expect(box.padding).toBe('10px')
    expect(box.inset).toBeCloseTo(10, 0)
    if (index > 0) expect(box.x - boxes[index - 1].right).toBeCloseTo(4, 0)
  }
  const add = (await page.locator('.project-detail-page__add-view').boundingBox())!
  expect(add.x - boxes.at(-1)!.right).toBeCloseTo(4, 0)
}

async function expectComposerSubmitAlignment(composer: Locator) {
  const inset = await composer.evaluate(element => {
    const box = element.getBoundingClientRect()
    const submit = element.querySelector('button.is-submit')!.getBoundingClientRect()
    return box.right - element.clientLeft - submit.right
  })
  expect(inset).toBeCloseTo(14, 0)
}

test.describe('mobile cycles timeline', () => {
  test.use({ isMobile: true, hasTouch: true, colorScheme: 'dark' })

  for (const width of [390, 375]) {
    test(`cycle cards, cooldown, chart and navigation at ${width}px`, async ({ page, request, workspaceKey }) => {
      const headers = { 'X-Flow-Workspace': workspaceKey, 'X-Workspace-Key': workspaceKey }
      const bootstrap = await (await request.get('/api/bootstrap', { headers })).json()
      const team = bootstrap.teams[0] as { id: string; key: string }
      expect((await request.patch(`/api/teams/${team.id}/cycle-settings`, { headers, data: { enabled: true, autoCreate: true, durationWeeks: 3, cooldownWeeks: 2, upcomingCount: 1 } })).ok()).toBe(true)
      const data = await (await request.get('/api/bootstrap', { headers })).json()
      const cycles = data.cycles as { id: string; number: number; startsAt: string; endsAt: string }[]
      const first = cycles.find(cycle => cycle.number === 1)!
      const next = cycles.find(cycle => cycle.number === 2)!
      expect((await request.patch(`/api/teams/${team.id}/cycle-settings`, { headers, data: { autoCreate: false } })).ok()).toBe(true)
      expect((await request.patch(`/api/cycles/${first.id}`, { headers, data: { status: 'completed', name: '[mobile] Finished cycle' } })).ok()).toBe(true)
