import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  createActivity as postActivity,
  type StravaDetailedActivity,
} from "../stravaClient";
import { createActivityTool } from "./createActivity";

vi.mock("../stravaClient", () => ({
  createActivity: vi.fn(),
}));

const mockedPost = vi.mocked(postActivity);

function createdActivity(
  overrides: Partial<StravaDetailedActivity> = {},
): StravaDetailedActivity {
  return {
    id: "9001",
    name: "Morning Yoga",
    sport_type: "Yoga",
    description: null,
    ...overrides,
  } as unknown as StravaDetailedActivity;
}

const baseInput = {
  name: "Morning Yoga",
  sportType: "Yoga" as const,
  startDateLocal: "2026-07-13T07:30:00",
  elapsedTimeSeconds: 1800,
};

describe("createActivityTool input schema", () => {
  it("rejects a sport type Strava does not define, before any write (#244)", () => {
    const result = createActivityTool.inputSchema.safeParse({
      ...baseInput,
      sportType: "Weightlifting",
    });

    expect(result.success).toBe(false);
    expect(result.error!.issues[0]!.message).toContain(
      "Did you mean WeightTraining?",
    );
    expect(mockedPost).not.toHaveBeenCalled();
  });

  it("accepts every sport type it advertises", () => {
    for (const sportType of ["Yoga", "TrailRun", "EMountainBikeRide"]) {
      expect(
        createActivityTool.inputSchema.safeParse({ ...baseInput, sportType })
          .success,
      ).toBe(true);
    }
  });
});

describe("createActivityTool.execute", () => {
  beforeEach(() => {
    process.env.STRAVA_ACCESS_TOKEN = "test-token";
    mockedPost.mockReset();
  });

  afterEach(() => {
    delete process.env.STRAVA_ACCESS_TOKEN;
  });

  it("creates a manual activity from the required fields", async () => {
    mockedPost.mockResolvedValueOnce(createdActivity());

    const result = await createActivityTool.execute(baseInput, "test-token");

    expect(mockedPost).toHaveBeenCalledWith("test-token", {
      name: "Morning Yoga",
