    enum: string[];
  };
  expect(summary.enum).toEqual(c.meetings.map((m) => m.label));
  for (const d of defs) {
    const p = JSON.stringify(d.function.parameters);
    expect(p).not.toContain("date_from");
    expect(p).not.toContain("date_to");
    expect(d.type).toBe("function");
  }
});

