    try {
      const result = await callDaemon<{ value: string }>(
        "ping",
        {},
        { socketPath: sock, timeoutMs: 2000 },
      );
      expect(result.value).toBe(value);
    } finally {
      splitter.close();
      try {
        fs.unlinkSync(sock);
      } catch {
        // ignore
      }
    }
