			const { app } = makeApp(root);
			try {
				assert.equal((await app.inject({ method: "GET", url: "/sessions/nope/events" })).statusCode, 404);
				assert.equal((await app.inject({ method: "DELETE", url: "/sessions/nope" })).statusCode, 404);
			} finally {
