function AuthStatusDisplay() {
  const { isAuthenticated, userId, displayName, isValidating } = useAuth();
  return (
    <div>
      <span data-testid="is-authenticated">{String(isAuthenticated)}</span>
      <span data-testid="user-id">{userId ?? "null"}</span>
